// The token map: closed names, grammars, error codes, limits, units, slider ranges, and the
// breakpoint preset. token-map.json is a copy of docs/contracts/tokens/v2/token-map.json,
// generated by scripts/build-contract.ts; a test keeps the copies identical.
import map from "./token-map.json" with { type: "json" };

export type Section = {
  section: string;
  kind: string;
  buildOnly?: boolean;
  tokens: Record<string, string | null>;
};

export type SliderRange = { min: number; max: number; step: number };

// Allowed units and slider ranges for one field, shared by validation and the wizard controls.
export type Field = {
  grammar: string;
  units: string[];
  defaultUnit: string;
  ranges: Record<string, SliderRange>;
};

type NumberRange = { min: number; max: number };

export type TokenMap = {
  contractVersion: number;
  generatorVersion: number;
  limits: { maxBytes: number; maxDepth: number };
  legacyVersions: Record<string, { grammars: Record<string, string> }>;
  grammars: Record<string, string>;
  errorCodes: Record<string, string>;
  theme: { parent: string };
  fontGenerics: string[];
  fontFallbacks: Record<string, string>;
  breakpointPreset: Record<string, string>;
  colorRanges: {
    rgbNumber: NumberRange;
    percent: NumberRange;
    hue: NumberRange;
    alphaNumber: NumberRange;
    oklchLightness: NumberRange;
    oklchChroma: NumberRange;
  };
  colorScheme: { option: string; values: string[]; default: string };
  shadowControls: Record<string, SliderRange & { unit: string }>;
  optionalSections: { section: string; kind: string; mirrors: string }[];
  fields: Record<string, Record<string, Field>>;
  sections: Section[];
};

export const tokenMap = map as TokenMap;
